fn main() {
    let p = Point { x: 0, y: 7 };
    let Point { x: a, y: b } = p;
    println!("a = {a}, b = {b}");

    match p {
        Point { x, y: 0 } => println!("On the x axis at {x}"),
        Point { x: 0, y } => println!("On the y axis at {y}"),
        Point { x, y } => println!("On neither axis: ({x}, {y})"),
    }

    let r = Rect { top_left: Point { x: 2, y: 3 }, width: 10, height: 4 };
    let Rect { top_left: Point { x, .. }, width, .. } = r;
    println!("left edge {x}, width {width}");
}

enum Color {
    Rgb(i32, i32, i32),
    Hsv(i32, i32, i32),
}

enum Message {
    Quit,
    Move { x: i32, y: i32 },
    Write(String),
    ChangeColor(Color),
}

fn handle(msg: Message) {
    match msg {
        Message::Quit => println!("The Quit variant has no data."),
        Message::Move { x, y } => println!("Move to x {x}, y {y}"),
        Message::Write(text) => println!("Text message: {text}"),
        Message::ChangeColor(Color::Rgb(r, g, b)) => {
            println!("Change color to red {r}, green {g}, blue {b}")
        }
        Message::ChangeColor(Color::Hsv(h, s, v)) => {
            println!("Change color to hue {h}, saturation {s}, value {v}")
        }
    }
}

fn main() {
    handle(Message::Move { x: 3, y: -1 });
    handle(Message::Write(String::from("hello")));
    handle(Message::ChangeColor(Color::Hsv(0, 160, 255)));
    handle(Message::Quit);

    let ((feet, inches), Point3 { x, .. }) = ((3, 10), Point3 { x: 3, y: -10, z: 0 });
    println!("{feet}'{inches}\" and x = {x}");
}

