fn describe(items: &[i32]) -> String {
    match items {
        [] => String::from("empty"),
        [one] => format!("one item: {one}"),
        [first, second] => format!("a pair: {first} and {second}"),
        [first, .., last] => format!("{} items from {first} to {last}", items.len()),
    }
}

fn sum(items: &[i32]) -> i32 {
    match items {
        [] => 0,
        [head, tail @ ..] => head + sum(tail),
    }
}

fn main() {
    let [r, g, b] = [255, 128, 0];
    println!("rgb {r} {g} {b}");
    for s in [&[][..], &[7], &[1, 2], &[1, 2, 3, 4]] {
        println!("{}", describe(s));
    }
    println!("sum {}", sum(&[1, 2, 3, 4]));
}

fn main() {
    let s = Some(String::from("Hello!"));

    if let Some(_) = s {
        println!("found a string");
    }
    println!("{s:?}"); // fine: `_` did not move the String

    let mut setting_value = Some(5);
    let new_setting_value = Some(10);
    match (setting_value, new_setting_value) {
        (Some(_), Some(_)) => println!("Can't overwrite an existing customized value"),
        _ => setting_value = new_setting_value,
    }
    println!("setting is {setting_value:?}");

    let numbers = (2, 4, 8, 16, 32);
    let (first, .., last) = numbers;
    println!("Some numbers: {first}, {last}");
}

