        match msg {
            Message::Hello { id: id @ 3..=7 } => println!("Found an id in range: {id}"),
            Message::Hello { id: 10..=12 } => println!("Found an id in another range"),
            Message::Hello { id } => println!("Found some other id: {id}"),
        }
    }
}

fn main() {
    let opt = Some(String::from("Ferris"));

    // default binding mode: matching on &opt binds name as &String
    match &opt {
        Some(name) => println!("hello, {name} ({} bytes)", name.len()),
        None => println!("nobody"),
    }

    // the same with an explicit `ref` on an owned value
    match opt {
        Some(ref name) => println!("still borrowed: {name}"),
        None => (),
    }
    println!("opt is still usable: {opt:?}");

    // `ref mut` and `&mut` default binding to change in place
    let mut pair = (1, String::from("a"));
    let (n, s) = &mut pair;
    *n += 1;
    s.push('!');
    println!("{pair:?}");

    // a & pattern copies the values out of a reference
    let points = [(1, 2), (3, 4)];
    for &(x, y) in points.iter() {
        print!("{} ", x + y);
    }
    println!();
}

